package net.zartra.gui;
import org.bukkit.Bukkit;import org.bukkit.entity.Player;import java.util.regex.*;
final class PlaceholderService {private final VariableStore variables;PlaceholderService(){this(new VariableStore());}PlaceholderService(VariableStore v){variables=v;}String replace(Player p,MenuDefinition m,String input){String r=input==null?"":input;r=safeReplace(r,"%menu%",m==null?"":m.title);r=safeReplace(r,"%menu_id%",m==null?"":m.id);r=safeReplace(r,"%server%",ServerNameResolver.resolve());if(p!=null)try{r=r.replace("%player%",safe(p.getName())).replace("%player_name%",safe(p.getName())).replace("%player_uuid%",String.valueOf(p.getUniqueId())).replace("%display_name%",safe(p.getDisplayName())).replace("%world%",safe(p.getWorld()==null?null:p.getWorld().getName())).replace("%x%",String.valueOf(p.getLocation().getBlockX())).replace("%y%",String.valueOf(p.getLocation().getBlockY())).replace("%z%",String.valueOf(p.getLocation().getBlockZ())).replace("%level%",String.valueOf(p.getLevel())).replace("%health%",String.valueOf(p.getHealth())).replace("%max_health%",String.valueOf(p.getMaxHealth())).replace("%food%",String.valueOf(p.getFoodLevel())).replace("%gamemode%",String.valueOf(p.getGameMode()));}catch(Throwable ignored){}try{r=r.replace("%online%",String.valueOf(Bukkit.getOnlinePlayers().size())).replace("%max_players%",String.valueOf(Bukkit.getMaxPlayers()));}catch(Throwable ignored){}r=variables(r,p,m);try{if(Bukkit.getPluginManager().getPlugin("PlaceholderAPI")!=null){Class<?> c=Class.forName("me.clip.placeholderapi.PlaceholderAPI");Object value=c.getMethod("setPlaceholders",Player.class,String.class).invoke(null,p,r);if(value instanceof String)r=(String)value;}}catch(Throwable ignored){}return r;}
 private String safe(String value){return value==null?"":value;}private String safeReplace(String value,String token,String replacement){return value.replace(token,safe(replacement));}
 private String variables(String input,Player p,MenuDefinition m){try{Matcher q=Pattern.compile("%var:([A-Za-z]+:[A-Za-z0-9_.-]+)%").matcher(input);StringBuffer out=new StringBuffer();while(q.find()){String value=p==null?null:variables.resolve(p.getUniqueId(),m==null?null:m.id,q.group(1));q.appendReplacement(out,Matcher.quoteReplacement(value==null?"":value));}q.appendTail(out);return out.toString();}catch(Throwable ignored){return input;}}
}